<?php
defined( 'ABSPATH' ) || exit;

function co_crm_register_types() {
	register_post_type( 'client_project', array( 'labels' => array( 'name' => 'Client Projects', 'singular_name' => 'Client Project' ), 'public' => false, 'show_ui' => true, 'show_in_menu' => false, 'supports' => array( 'title' ), 'capability_type' => 'post', 'map_meta_cap' => true ) );
	register_post_type( 'project_payment', array( 'labels' => array( 'name' => 'Project Payments', 'singular_name' => 'Project Payment' ), 'public' => false, 'show_ui' => true, 'show_in_menu' => false, 'supports' => array( 'title' ), 'capability_type' => 'post', 'map_meta_cap' => true ) );
}
add_action( 'init', 'co_crm_register_types' );

add_action( 'admin_menu', function () {
	add_menu_page( 'Client Projects', 'Projects CRM', 'edit_posts', 'co-projects', 'co_crm_dashboard', 'dashicons-chart-line', 24 );
	add_submenu_page( 'co-projects', 'Pipeline', 'Pipeline', 'edit_posts', 'co-projects', 'co_crm_dashboard' );
	add_submenu_page( 'co-projects', 'Annual Revenue', 'Annual Report', 'edit_posts', 'co-project-report', 'co_crm_report' );
	add_submenu_page( null, 'Project Details', 'Project Details', 'edit_posts', 'co-project-detail', 'co_crm_detail' );
} );

add_action( 'wp_ajax_co_crm_move_stage', function () {
	if ( ! current_user_can( 'edit_posts' ) || ! check_ajax_referer( 'co_crm_move_stage', 'nonce', false ) ) wp_send_json_error( array( 'message' => 'Permission denied.' ), 403 );
	$id = absint( $_POST['project_id'] ?? 0 ); $stage = sanitize_key( $_POST['stage'] ?? '' );
	if ( 'client_project' !== get_post_type( $id ) || ! isset( co_crm_stages()[$stage] ) ) wp_send_json_error( array( 'message' => 'Invalid project or stage.' ), 400 );
	update_post_meta( $id, '_crm_stage', $stage ); wp_send_json_success( array( 'stage' => $stage ) );
} );

function co_crm_meta( $id, $key, $default = '' ) { $value = get_post_meta( $id, '_crm_' . $key, true ); return '' === $value ? $default : $value; }
function co_crm_money( $value ) { return number_format( (float) $value, 2 ); }
function co_crm_projects() { return get_posts( array( 'post_type' => 'client_project', 'post_status' => 'publish', 'numberposts' => -1, 'orderby' => 'date', 'order' => 'DESC' ) ); }
function co_crm_payments( $project_id = 0 ) { $args = array( 'post_type' => 'project_payment', 'post_status' => 'publish', 'numberposts' => -1, 'meta_key' => '_crm_paid_date', 'orderby' => 'meta_value', 'order' => 'DESC' ); if ( $project_id ) $args['meta_query'] = array( array( 'key' => '_crm_project_id', 'value' => $project_id ) ); return get_posts( $args ); }
function co_crm_received( $project_id ) { $total = 0; foreach ( co_crm_payments( $project_id ) as $payment ) $total += (float) co_crm_meta( $payment->ID, 'amount' ); return $total; }
function co_crm_onboarding_brief( $submission_id ) {
	$parts = array();
	$labels = array( 'business_description' => 'Business overview', 'services' => 'Products / services', 'notes' => 'Additional notes' );
	foreach ( $labels as $key => $label ) {
		$value = trim( (string) get_post_meta( $submission_id, '_onboarding_' . $key, true ) );
		if ( $value ) $parts[] = $label . ":\n" . $value;
	}
	return implode( "\n\n", $parts );
}
function co_crm_project_brief( $project_id ) {
	$brief = (string) co_crm_meta( $project_id, 'brief' );
	if ( $brief ) return $brief;
	$onboarding_id = absint( co_crm_meta( $project_id, 'onboarding_id' ) );
	return $onboarding_id ? co_crm_onboarding_brief( $onboarding_id ) : '';
}
function co_crm_asset_mimes() { return array_merge( co_allowed_mimes(), array( 'gif' => 'image/gif', 'txt' => 'text/plain', 'ppt' => 'application/vnd.ms-powerpoint', 'pptx' => 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 'woff' => 'font/woff', 'woff2' => 'font/woff2', 'ttf' => 'font/ttf', 'otf' => 'font/otf' ) ); }
add_filter( 'upload_mimes', function ( $mimes ) { return current_user_can( 'upload_files' ) ? array_merge( $mimes, co_crm_asset_mimes() ) : $mimes; } );
function co_crm_project_assets( $project_id ) {
	$items = array(); foreach ( (array) co_crm_meta( $project_id, 'asset_ids', array() ) as $id ) if ( get_post( $id ) ) $items[$id] = 'Project';
	$onboarding_id = absint( co_crm_meta( $project_id, 'onboarding_id' ) ); if ( $onboarding_id ) { foreach ( (array) get_post_meta( $onboarding_id, '_onboarding_uploaded_files', true ) as $id ) if ( get_post( $id ) ) $items[$id] = 'Onboarding'; $sitemap = absint( get_post_meta( $onboarding_id, '_onboarding_sitemap_file', true ) ); if ( $sitemap && get_post( $sitemap ) ) $items[$sitemap] = 'Onboarding sitemap'; }
	return $items;
}
function co_crm_render_assets( $project_id ) {
	$assets = co_crm_project_assets( $project_id ); if ( ! $assets ) { echo '<p class="crm-assets-empty">No assets yet. Upload project files below.</p>'; return; }
	echo '<div class="crm-assets-grid">'; foreach ( $assets as $attachment_id => $source ) { $url = wp_get_attachment_url( $attachment_id ); if ( ! $url ) continue; $mime = (string) get_post_mime_type( $attachment_id ); $name = get_the_title( $attachment_id ) ?: basename( get_attached_file( $attachment_id ) ); $icon = 0 === strpos( $mime, 'image/' ) ? wp_get_attachment_image( $attachment_id, 'thumbnail', false, array( 'loading' => 'lazy' ) ) : '<span class="crm-file-icon">' . esc_html( strtoupper( pathinfo( $url, PATHINFO_EXTENSION ) ?: 'FILE' ) ) . '</span>'; echo '<a href="' . esc_url( $url ) . '" target="_blank" rel="noopener"><span class="crm-asset-preview">' . $icon . '</span><span class="crm-asset-copy"><b>' . esc_html( $name ) . '</b><small>' . esc_html( $source ) . '</small></span><i>↗</i></a>'; } echo '</div>';
}
function co_crm_handle_asset_uploads( $project_id ) {
	if ( empty( $_FILES['project_assets']['name'] ) || ! current_user_can( 'upload_files' ) ) return;
	$files = $_FILES['project_assets']; $names = is_array( $files['name'] ) ? $files['name'] : array( $files['name'] ); if ( count( $names ) > 20 ) wp_die( 'A maximum of 20 assets can be uploaded at once.' );
	require_once ABSPATH . 'wp-admin/includes/file.php'; require_once ABSPATH . 'wp-admin/includes/media.php'; require_once ABSPATH . 'wp-admin/includes/image.php'; $ids = (array) co_crm_meta( $project_id, 'asset_ids', array() );
	foreach ( $names as $index => $name ) { if ( ! $name ) continue; $size = is_array( $files['size'] ) ? $files['size'][$index] : $files['size']; if ( (int) $size > 20 * MB_IN_BYTES ) continue; $_FILES['crm_asset_single'] = array( 'name' => $name, 'type' => is_array( $files['type'] ) ? $files['type'][$index] : $files['type'], 'tmp_name' => is_array( $files['tmp_name'] ) ? $files['tmp_name'][$index] : $files['tmp_name'], 'error' => is_array( $files['error'] ) ? $files['error'][$index] : $files['error'], 'size' => $size ); $attachment_id = media_handle_upload( 'crm_asset_single', $project_id, array(), array( 'test_form' => false, 'mimes' => co_crm_asset_mimes() ) ); if ( ! is_wp_error( $attachment_id ) ) $ids[] = $attachment_id; }
	unset( $_FILES['crm_asset_single'] ); update_post_meta( $project_id, '_crm_asset_ids', array_values( array_unique( array_map( 'absint', $ids ) ) ) );
}
function co_crm_stages() { return array( 'brief' => 'Brief received', 'quotation' => 'Quotation', 'timeline' => 'Timeline', 'doing' => 'Doing', 'waiting_client' => 'Waiting for client', 'ma' => 'MA', 'done' => 'Done' ); }
function co_crm_project_stage( $project_id ) {
	$stage = co_crm_meta( $project_id, 'stage', 'brief' ); $legacy = array( 'approved' => 'timeline', 'production' => 'doing', 'handover' => 'done', 'closed' => 'done', 'lost' => 'done' );
	if ( isset( $legacy[$stage] ) ) { $stage = $legacy[$stage]; update_post_meta( $project_id, '_crm_stage', $stage ); }
	return isset( co_crm_stages()[$stage] ) ? $stage : 'brief';
}
function co_crm_sync_onboarding_project( $submission_id, $data = array() ) {
	if ( get_post_meta( $submission_id, '_onboarding_skip_project', true ) ) return 0;
	$linked = absint( get_post_meta( $submission_id, '_onboarding_project_id', true ) ); if ( $linked && 'client_project' === get_post_type( $linked ) ) return $linked;
	$existing = get_posts( array( 'post_type' => 'client_project', 'post_status' => 'publish', 'numberposts' => 1, 'meta_key' => '_crm_onboarding_id', 'meta_value' => $submission_id ) ); if ( $existing ) { update_post_meta( $submission_id, '_onboarding_project_id', $existing[0]->ID ); return $existing[0]->ID; }
	$get = function ( $key ) use ( $submission_id, $data ) { return $data[$key] ?? get_post_meta( $submission_id, '_onboarding_' . $key, true ); }; $company = $get( 'company_name' ) ?: get_the_title( $submission_id );
	$id = wp_insert_post( array( 'post_type' => 'client_project', 'post_status' => 'publish', 'post_title' => $company ) ); if ( is_wp_error( $id ) || ! $id ) return 0;
	update_post_meta( $id, '_crm_company', $company ); update_post_meta( $id, '_crm_contact_name', $get( 'contact_name' ) ); update_post_meta( $id, '_crm_contact_email', $get( 'email' ) ); update_post_meta( $id, '_crm_deadline', $get( 'target_launch' ) ); update_post_meta( $id, '_crm_brief', co_crm_onboarding_brief( $submission_id ) ); update_post_meta( $id, '_crm_stage', 'brief' ); update_post_meta( $id, '_crm_onboarding_id', $submission_id ); update_post_meta( $submission_id, '_onboarding_project_id', $id ); update_post_meta( $submission_id, '_onboarding_status', 'project_created' ); return $id;
}

add_filter( 'post_row_actions', function ( $actions, $post ) {
	if ( 'onboarding_submit' !== $post->post_type ) return $actions;
	$actions['crm_project'] = '<a href="' . esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=co_crm_from_onboarding&submission=' . $post->ID ), 'co_crm_from_' . $post->ID ) ) . '">Create project</a>';
	return $actions;
}, 10, 2 );
add_action( 'admin_post_co_crm_from_onboarding', function () {
	if ( ! current_user_can( 'edit_posts' ) ) wp_die( 'Permission denied.' ); $submission_id = absint( $_GET['submission'] ?? 0 ); check_admin_referer( 'co_crm_from_' . $submission_id );
	$existing = get_posts( array( 'post_type' => 'client_project', 'post_status' => 'publish', 'numberposts' => 1, 'meta_key' => '_crm_onboarding_id', 'meta_value' => $submission_id ) );
	if ( $existing ) { $id = $existing[0]->ID; } else { $company = get_post_meta( $submission_id, '_onboarding_company_name', true ); $id = wp_insert_post( array( 'post_type' => 'client_project', 'post_status' => 'publish', 'post_title' => $company ?: get_the_title( $submission_id ) ) ); update_post_meta( $id, '_crm_company', $company ?: get_the_title( $submission_id ) ); update_post_meta( $id, '_crm_contact_name', get_post_meta( $submission_id, '_onboarding_contact_name', true ) ); update_post_meta( $id, '_crm_contact_email', get_post_meta( $submission_id, '_onboarding_email', true ) ); update_post_meta( $id, '_crm_deadline', get_post_meta( $submission_id, '_onboarding_target_launch', true ) ); update_post_meta( $id, '_crm_brief', co_crm_onboarding_brief( $submission_id ) ); update_post_meta( $id, '_crm_stage', 'brief' ); update_post_meta( $id, '_crm_onboarding_id', $submission_id ); update_post_meta( $submission_id, '_onboarding_project_id', $id ); }
	wp_safe_redirect( admin_url( 'admin.php?page=co-project-detail&project=' . $id ) ); exit;
} );
add_action( 'admin_post_co_crm_delete_project', function () {
	if ( ! current_user_can( 'delete_posts' ) ) wp_die( 'Permission denied.' ); $id = absint( $_GET['project_id'] ?? 0 ); check_admin_referer( 'co_crm_delete_' . $id ); if ( 'client_project' !== get_post_type( $id ) ) wp_die( 'Invalid project.' );
	$onboarding_id = absint( co_crm_meta( $id, 'onboarding_id' ) ); if ( $onboarding_id ) { update_post_meta( $onboarding_id, '_onboarding_skip_project', '1' ); update_post_meta( $onboarding_id, '_onboarding_status', 'project_deleted' ); delete_post_meta( $onboarding_id, '_onboarding_project_id' ); }
	foreach ( co_crm_payments( $id ) as $payment ) wp_trash_post( $payment->ID ); wp_trash_post( $id ); wp_safe_redirect( admin_url( 'admin.php?page=co-projects&deleted=1' ) ); exit;
} );

function co_crm_assets() { ?>
	<style><?php include CO_THEME_DIR . '/assets/project-crm.css'; ?></style>
	<script>document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-crm-open]').forEach(b=>b.addEventListener('click',()=>document.querySelector('[data-crm-modal="'+b.dataset.crmOpen+'"]').classList.add('open')));document.querySelectorAll('.crm-modal,.crm-close').forEach(el=>el.addEventListener('click',e=>{if(e.target===el||e.target.classList.contains('crm-close'))el.closest('.crm-modal')?.classList.remove('open')}));const select=document.querySelector('#crm-onboarding-source'),form=select?.closest('form');select?.addEventListener('change',()=>{const data=select.selectedOptions[0]?.dataset;if(!data||!select.value)return;const values={project_name:data.company,company:data.company,contact_name:data.contact,contact_email:data.email,deadline:data.deadline};Object.entries(values).forEach(([name,value])=>{const input=form.querySelector('[name="'+name+'"]');if(input&&value)input.value=value});form.querySelector('.crm-import-note').textContent='Imported from onboarding submission #'+select.value})});</script>
	<script>
	document.addEventListener('DOMContentLoaded', function () {
		let draggedCard = null;
		let suppressCardClick = false;
		const board = document.querySelector('.crm-board');
		const closeDrawer = function ( drawer ) { drawer.classList.remove('open'); document.body.classList.remove('crm-drawer-open'); };
		const updateCount = function ( column ) { const count = column && column.querySelector('.crm-count'); if ( count ) count.textContent = column.querySelectorAll('.crm-card').length; };

		document.querySelectorAll('.crm-card[data-project]').forEach(function ( card ) {
			card.addEventListener('dragstart', function () { draggedCard = card; suppressCardClick = true; card.classList.add('dragging'); });
			card.addEventListener('dragend', function () { card.classList.remove('dragging'); document.querySelectorAll('.crm-column').forEach(function ( column ) { column.classList.remove('drag-over'); }); setTimeout(function () { suppressCardClick = false; }, 180); });
			card.addEventListener('click', function ( event ) { if ( suppressCardClick || event.target.closest('a,button') ) return; const drawer = document.querySelector('[data-crm-drawer="' + card.dataset.project + '"]'); if ( drawer ) { drawer.classList.add('open'); document.body.classList.add('crm-drawer-open'); } });
			card.addEventListener('keydown', function ( event ) { if ( event.key === 'Enter' || event.key === ' ' ) { event.preventDefault(); card.click(); } });
		});

		document.querySelectorAll('.crm-column').forEach(function ( column ) {
			column.addEventListener('dragover', function ( event ) { event.preventDefault(); column.classList.add('drag-over'); });
			column.addEventListener('dragleave', function () { column.classList.remove('drag-over'); });
			column.addEventListener('drop', async function ( event ) {
				event.preventDefault(); column.classList.remove('drag-over');
				if ( ! draggedCard || draggedCard.dataset.stage === column.dataset.stage || ! board ) return;
				const oldColumn = draggedCard.closest('.crm-column');
				const body = new URLSearchParams({ action: 'co_crm_move_stage', project_id: draggedCard.dataset.project, stage: column.dataset.stage, nonce: board.dataset.nonce });
				try {
					const response = await fetch(window.ajaxurl, { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: body.toString() });
					const result = await response.json();
					if ( ! result.success ) throw new Error('Move failed');
					column.appendChild(draggedCard); draggedCard.dataset.stage = column.dataset.stage; updateCount(oldColumn); updateCount(column);
					const drawer = document.querySelector('[data-crm-drawer="' + draggedCard.dataset.project + '"]');
					if ( drawer ) { const status = drawer.querySelector('.crm-drawer-status'); const select = drawer.querySelector('select[name="stage"]'); if ( status ) status.textContent = column.dataset.label; if ( select ) select.value = column.dataset.stage; }
				} catch ( error ) { window.location.reload(); }
			});
		});

		document.querySelectorAll('.crm-drawer').forEach(function ( drawer ) { drawer.addEventListener('click', function ( event ) { if ( event.target === drawer || event.target.closest('.crm-drawer-close') ) closeDrawer(drawer); }); });
		document.addEventListener('keydown', function ( event ) { if ( event.key === 'Escape' ) document.querySelectorAll('.crm-drawer.open').forEach(closeDrawer); });
		const reopenId = new URLSearchParams(window.location.search).get('open_project'); const reopenDrawer = reopenId && document.querySelector('[data-crm-drawer="' + reopenId + '"]'); if ( reopenDrawer ) { reopenDrawer.classList.add('open'); document.body.classList.add('crm-drawer-open'); }
	});
	</script>
<?php }

function co_crm_dashboard() {
	if ( ! current_user_can( 'edit_posts' ) ) return;
	foreach ( get_posts( array( 'post_type' => 'onboarding_submit', 'post_status' => 'any', 'numberposts' => -1, 'fields' => 'ids' ) ) as $submission_id ) co_crm_sync_onboarding_project( $submission_id );
	$projects = co_crm_projects(); $stages = co_crm_stages(); co_crm_assets(); ?>
	<div class="crm-wrap"><header class="crm-hero"><div><small>PROJECT OPERATIONS</small><h1>Client Project Pipeline</h1><p>From onboarding and quotation through delivery and MA.</p></div><div><a class="crm-btn ghost" href="<?php echo esc_url( admin_url( 'admin.php?page=co-project-report' ) ); ?>">Annual report</a><button class="crm-btn white" data-crm-open="project">+ New project</button></div></header>
	<section class="crm-stats"><div><small>Projects</small><strong><?php echo count( $projects ); ?></strong></div><div><small>Approved value</small><strong>฿<?php echo co_crm_money( array_sum( array_map( fn( $p ) => (float) co_crm_meta( $p->ID, 'net_total' ), $projects ) ) ); ?></strong></div><div><small>Cash received</small><strong>฿<?php echo co_crm_money( array_sum( array_map( fn( $p ) => co_crm_received( $p->ID ), $projects ) ) ); ?></strong></div><div><small>Outstanding</small><strong>฿<?php echo co_crm_money( array_sum( array_map( fn( $p ) => max( 0, (float) co_crm_meta( $p->ID, 'net_total' ) - co_crm_received( $p->ID ) ), $projects ) ) ); ?></strong></div></section>
	<div class="crm-board" data-nonce="<?php echo esc_attr( wp_create_nonce( 'co_crm_move_stage' ) ); ?>"><?php foreach ( $stages as $stage => $label ) : ?><section class="crm-column" data-stage="<?php echo esc_attr( $stage ); ?>" data-label="<?php echo esc_attr( $label ); ?>"><header><h2><?php echo esc_html( $label ); ?></h2><span class="crm-count"><?php echo count( array_filter( $projects, fn( $p ) => $stage === co_crm_project_stage( $p->ID ) ) ); ?></span></header><?php foreach ( $projects as $project ) : if ( $stage !== co_crm_project_stage( $project->ID ) ) continue; $total = (float) co_crm_meta( $project->ID, 'net_total' ); $received = co_crm_received( $project->ID ); $onboarding_id = absint( co_crm_meta( $project->ID, 'onboarding_id' ) ); ?><article class="crm-card" draggable="true" tabindex="0" role="button" data-project="<?php echo $project->ID; ?>" data-stage="<?php echo esc_attr( $stage ); ?>"><small><?php echo esc_html( co_crm_meta( $project->ID, 'company', 'Client' ) ); ?></small><h3><?php echo esc_html( $project->post_title ); ?></h3><p><?php echo esc_html( co_crm_meta( $project->ID, 'current_task', 'No current task' ) ); ?></p><div><b>฿<?php echo co_crm_money( $total ); ?></b><span><?php echo esc_html( co_ma_date( co_crm_meta( $project->ID, 'deadline' ) ) ); ?></span></div><?php if ( $onboarding_id && 'onboarding_submit' === get_post_type( $onboarding_id ) ) : ?><a class="crm-card-brief" href="<?php echo esc_url( get_permalink( $onboarding_id ) ); ?>" target="_blank" rel="noopener">View full brief <span>↗</span></a><?php endif; ?><i style="width:<?php echo $total ? esc_attr( min( 100, $received / $total * 100 ) ) : 0; ?>%"></i></article><?php endforeach; ?></section><?php endforeach; ?></div></div>
	<?php foreach ( $projects as $project ) co_crm_drawer( $project ); ?>
	<?php co_crm_project_modal();
}

function co_crm_drawer( $project ) {
	$id = $project->ID; $total = (float) co_crm_meta( $id, 'net_total' ); $received = co_crm_received( $id ); $return_url = add_query_arg( 'open_project', $id, admin_url( 'admin.php?page=co-projects' ) ); $ma_client_id = absint( co_crm_meta( $id, 'ma_client_id' ) ); ?>
	<div class="crm-drawer" data-crm-drawer="<?php echo $id; ?>"><aside>
		<header><div><small><?php echo esc_html( co_crm_meta( $id, 'company', 'CLIENT PROJECT' ) ); ?></small><h2><?php echo esc_html( $project->post_title ); ?></h2><p class="crm-drawer-status"><?php echo esc_html( co_crm_stages()[co_crm_project_stage( $id )] ); ?></p></div><button class="crm-drawer-close" type="button">×</button></header>
		<div class="crm-drawer-body">
			<section class="crm-drawer-summary"><div><small>Project value</small><strong>฿<?php echo co_crm_money( $total ); ?></strong></div><div><small>Received</small><strong>฿<?php echo co_crm_money( $received ); ?></strong></div><div><small>Outstanding</small><strong>฿<?php echo co_crm_money( max( 0, $total - $received ) ); ?></strong></div></section>
