add_action( 'admin_post_co_crm_save', function () {
	if ( ! current_user_can( 'edit_posts' ) ) wp_die( 'Permission denied.' ); check_admin_referer( 'co_crm_save' ); $entity = sanitize_key( $_POST['entity'] ?? '' ); $return_url = esc_url_raw( wp_unslash( $_POST['return_url'] ?? '' ) );
	if ( 'project' === $entity ) { $id = wp_insert_post( array( 'post_type' => 'client_project', 'post_status' => 'publish', 'post_title' => sanitize_text_field( wp_unslash( $_POST['project_name'] ?? '' ) ) ) ); $fields = array( 'company','contact_name','contact_email','quotation_no','net_total','cost','start_date','deadline','timeline_url' ); foreach ( $fields as $field ) update_post_meta( $id, '_crm_' . $field, 'contact_email' === $field ? sanitize_email( wp_unslash( $_POST[$field] ?? '' ) ) : ( 'timeline_url' === $field ? esc_url_raw( wp_unslash( $_POST[$field] ?? '' ) ) : sanitize_text_field( wp_unslash( $_POST[$field] ?? '' ) ) ) ); $onboarding_id = absint( $_POST['onboarding_id'] ?? 0 ); $brief = sanitize_textarea_field( wp_unslash( $_POST['brief'] ?? '' ) ); if ( ! $brief && $onboarding_id ) $brief = co_crm_onboarding_brief( $onboarding_id ); update_post_meta( $id, '_crm_brief', $brief ); update_post_meta( $id, '_crm_stage', 'brief' ); if ( $onboarding_id && 'onboarding_submit' === get_post_type( $onboarding_id ) ) { update_post_meta( $id, '_crm_onboarding_id', $onboarding_id ); update_post_meta( $onboarding_id, '_onboarding_project_id', $id ); update_post_meta( $onboarding_id, '_onboarding_status', 'project_created' ); } co_crm_handle_asset_uploads( $id ); $redirect = admin_url( 'admin.php?page=co-project-detail&project=' . $id ); }
	elseif ( 'update' === $entity ) { $id = absint( $_POST['project_id'] ?? 0 ); if ( 'client_project' !== get_post_type( $id ) ) wp_die( 'Invalid project.' ); $project_name = sanitize_text_field( wp_unslash( $_POST['project_name'] ?? '' ) ); if ( $project_name ) wp_update_post( array( 'ID' => $id, 'post_title' => $project_name ) ); $stage = sanitize_key( $_POST['stage'] ?? 'brief' ); if ( ! isset( co_crm_stages()[$stage] ) ) $stage = 'brief'; foreach ( array( 'company','contact_name','contact_email','quotation_no','net_total','cost','start_date','deadline','timeline_url','current_task' ) as $field ) update_post_meta( $id, '_crm_' . $field, 'contact_email' === $field ? sanitize_email( wp_unslash( $_POST[$field] ?? '' ) ) : ( 'timeline_url' === $field ? esc_url_raw( wp_unslash( $_POST[$field] ?? '' ) ) : sanitize_text_field( wp_unslash( $_POST[$field] ?? '' ) ) ) ); update_post_meta( $id, '_crm_brief', sanitize_textarea_field( wp_unslash( $_POST['brief'] ?? '' ) ) ); update_post_meta( $id, '_crm_stage', $stage ); $redirect = $return_url ?: admin_url( 'admin.php?page=co-project-detail&project=' . $id ); }
	elseif ( 'payment' === $entity ) { $project_id = absint( $_POST['project_id'] ?? 0 ); $amount = max( 0, (float) ( $_POST['amount'] ?? 0 ) ); $id = wp_insert_post( array( 'post_type' => 'project_payment', 'post_status' => 'publish', 'post_title' => sanitize_text_field( wp_unslash( $_POST['label'] ?? 'Project payment' ) ) ) ); update_post_meta( $id, '_crm_project_id', $project_id ); update_post_meta( $id, '_crm_amount', $amount ); update_post_meta( $id, '_crm_paid_date', sanitize_text_field( $_POST['paid_date'] ?? wp_date( 'Y-m-d' ) ) ); update_post_meta( $id, '_crm_note', sanitize_textarea_field( wp_unslash( $_POST['note'] ?? '' ) ) ); $redirect = $return_url ?: admin_url( 'admin.php?page=co-project-detail&project=' . $project_id ); }
	elseif ( 'assets' === $entity ) { $project_id = absint( $_POST['project_id'] ?? 0 ); if ( 'client_project' !== get_post_type( $project_id ) ) wp_die( 'Invalid project.' ); co_crm_handle_asset_uploads( $project_id ); $redirect = $return_url ?: admin_url( 'admin.php?page=co-project-detail&project=' . $project_id ); }
	elseif ( 'start_ma' === $entity ) { $project_id = absint( $_POST['project_id'] ?? 0 ); if ( 'client_project' !== get_post_type( $project_id ) ) wp_die( 'Invalid project.' ); $existing = absint( co_crm_meta( $project_id, 'ma_client_id' ) ); if ( $existing && 'ma_client' === get_post_type( $existing ) ) { $redirect = admin_url( 'admin.php?page=ma-client-detail&client=' . $existing ); } else { $hours = max( .25, (float) ( $_POST['hours'] ?? 0 ) ); $start = sanitize_text_field( $_POST['start_date'] ?? wp_date( 'Y-m-d' ) ); $duration = sanitize_key( $_POST['duration'] ?? '3m' ); $months = array( '3m' => 3, '6m' => 6, '1y' => 12 ); if ( ! isset( $months[$duration] ) ) $duration = '3m'; $ma_id = wp_insert_post( array( 'post_type' => 'ma_client', 'post_status' => 'publish', 'post_title' => co_crm_meta( $project_id, 'company', get_the_title( $project_id ) ) ) ); update_post_meta( $ma_id, '_ma_purchased_hours', $hours ); update_post_meta( $ma_id, '_ma_package_type', in_array( sanitize_key( $_POST['package_type'] ?? '' ), array( 'hour_bank','monthly_retainer' ), true ) ? sanitize_key( $_POST['package_type'] ) : 'hour_bank' ); update_post_meta( $ma_id, '_ma_contact_name', co_crm_meta( $project_id, 'contact_name' ) ); update_post_meta( $ma_id, '_ma_contact_email', co_crm_meta( $project_id, 'contact_email' ) ); update_post_meta( $ma_id, '_ma_start_date', $start ); update_post_meta( $ma_id, '_ma_duration', $duration ); update_post_meta( $ma_id, '_ma_expiry_date', gmdate( 'Y-m-d', strtotime( '+' . $months[$duration] . ' months', strtotime( $start ) ) ) ); update_post_meta( $ma_id, '_ma_status', 'active' ); co_ma_share_token( $ma_id ); $ma_project = wp_insert_post( array( 'post_type' => 'ma_project', 'post_status' => 'publish', 'post_title' => get_the_title( $project_id ) ) ); update_post_meta( $ma_project, '_ma_client_id', $ma_id ); update_post_meta( $ma_project, '_ma_status', 'active' ); update_post_meta( $ma_project, '_ma_description', co_crm_project_brief( $project_id ) ); update_post_meta( $ma_project, '_ma_crm_project_id', $project_id ); update_post_meta( $project_id, '_crm_ma_project_id', $ma_project ); update_post_meta( $project_id, '_crm_ma_client_id', $ma_id ); update_post_meta( $project_id, '_crm_stage', 'ma' ); $redirect = admin_url( 'admin.php?page=ma-client-detail&client=' . $ma_id ); } }
	wp_safe_redirect( add_query_arg( 'saved', '1', $redirect ?? admin_url( 'admin.php?page=co-projects' ) ) ); exit;
} );

function co_crm_detail() {
	$id = absint( $_GET['project'] ?? 0 ); $project = get_post( $id ); if ( ! $project || 'client_project' !== $project->post_type ) { echo '<div class="wrap"><h1>Project not found</h1></div>'; return; } $payments = co_crm_payments( $id ); $total = (float) co_crm_meta( $id, 'net_total' ); $cost = (float) co_crm_meta( $id, 'cost' ); $received = co_crm_received( $id ); co_crm_assets(); ?>
	<div class="crm-wrap crm-detail"><a class="crm-back" href="<?php echo esc_url( admin_url( 'admin.php?page=co-projects' ) ); ?>">← Pipeline</a><header class="crm-detail-head"><div><small><?php echo esc_html( co_crm_meta( $id, 'company' ) ); ?></small><h1><?php echo esc_html( $project->post_title ); ?></h1><p><?php echo esc_html( co_crm_stages()[co_crm_meta( $id, 'stage', 'brief' )] ?? 'Brief received' ); ?></p></div><?php if ( co_crm_meta( $id, 'timeline_url' ) ) : ?><a target="_blank" class="crm-btn ghost-dark" href="<?php echo esc_url( co_crm_meta( $id, 'timeline_url' ) ); ?>">Open Google Sheet ↗</a><?php endif; ?></header>
	<section class="crm-finance"><div><small>Project value</small><strong>฿<?php echo co_crm_money( $total ); ?></strong></div><div><small>Received</small><strong>฿<?php echo co_crm_money( $received ); ?></strong></div><div><small>Outstanding</small><strong>฿<?php echo co_crm_money( max( 0, $total - $received ) ); ?></strong></div><div><small>Gross profit</small><strong>฿<?php echo co_crm_money( $total - $cost ); ?></strong></div></section>
	<div class="crm-detail-grid"><section class="crm-panel"><h2>Project information</h2><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'co_crm_save' ); ?><input type="hidden" name="action" value="co_crm_save"><input type="hidden" name="entity" value="update"><input type="hidden" name="project_id" value="<?php echo $id; ?>"><div class="crm-grid"><label>Stage<select name="stage"><?php foreach ( co_crm_stages() as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( co_crm_meta( $id, 'stage', 'brief' ), $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label><label>Company<input name="company" value="<?php echo esc_attr( co_crm_meta( $id, 'company' ) ); ?>"></label><label>Contact<input name="contact_name" value="<?php echo esc_attr( co_crm_meta( $id, 'contact_name' ) ); ?>"></label><label>Email<input type="email" name="contact_email" value="<?php echo esc_attr( co_crm_meta( $id, 'contact_email' ) ); ?>"></label><label>Quotation no.<input name="quotation_no" value="<?php echo esc_attr( co_crm_meta( $id, 'quotation_no' ) ); ?>"></label><label>Project value<input type="number" step=".01" name="net_total" value="<?php echo esc_attr( $total ); ?>"></label><label>Cost estimate<input type="number" step=".01" name="cost" value="<?php echo esc_attr( $cost ); ?>"></label><label>Current task<input name="current_task" value="<?php echo esc_attr( co_crm_meta( $id, 'current_task' ) ); ?>"></label><label>Start date<input type="date" name="start_date" value="<?php echo esc_attr( co_crm_meta( $id, 'start_date' ) ); ?>"></label><label>Deadline<input type="date" name="deadline" value="<?php echo esc_attr( co_crm_meta( $id, 'deadline' ) ); ?>"></label></div><label>Google Sheet timeline<input type="url" name="timeline_url" value="<?php echo esc_attr( co_crm_meta( $id, 'timeline_url' ) ); ?>"></label><label>Project brief / Internal notes<textarea name="brief" rows="10"><?php echo esc_textarea( co_crm_project_brief( $id ) ); ?></textarea></label><button class="crm-btn" type="submit">Save project</button></form></section>
	<section class="crm-panel"><h2>Record payment</h2><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'co_crm_save' ); ?><input type="hidden" name="action" value="co_crm_save"><input type="hidden" name="entity" value="payment"><input type="hidden" name="project_id" value="<?php echo $id; ?>"><label>Payment label<input required name="label" placeholder="Deposit / Final payment"></label><div class="crm-grid"><label>Amount<input required type="number" min="0.01" step=".01" name="amount"></label><label>Received date<input required type="date" name="paid_date" value="<?php echo esc_attr( wp_date( 'Y-m-d' ) ); ?>"></label></div><label>Note<textarea name="note" rows="2"></textarea></label><button class="crm-btn" type="submit">Add payment</button></form><div class="crm-payment-list"><?php foreach ( $payments as $payment ) : ?><article><div><b><?php echo esc_html( $payment->post_title ); ?></b><small><?php echo esc_html( co_ma_date( co_crm_meta( $payment->ID, 'paid_date' ) ) ); ?></small></div><strong>฿<?php echo co_crm_money( co_crm_meta( $payment->ID, 'amount' ) ); ?></strong></article><?php endforeach; ?></div></section></div>
