function co_crm_report() {
	$year = min( 2100, max( 2000, absint( $_GET['report_year'] ?? wp_date( 'Y' ) ) ) ); $projects = co_crm_projects(); $sales = $cash = $cost = 0; $months = array_fill( 1, 12, 0 ); foreach ( $projects as $project ) { $date = co_crm_meta( $project->ID, 'start_date', get_the_date( 'Y-m-d', $project ) ); if ( (int) substr( $date, 0, 4 ) === $year ) { $sales += (float) co_crm_meta( $project->ID, 'net_total' ); $cost += (float) co_crm_meta( $project->ID, 'cost' ); } } foreach ( co_crm_payments() as $payment ) { $date = co_crm_meta( $payment->ID, 'paid_date' ); if ( (int) substr( $date, 0, 4 ) === $year ) { $amount = (float) co_crm_meta( $payment->ID, 'amount' ); $cash += $amount; $months[(int) substr( $date, 5, 2 )] += $amount; } } co_crm_assets(); ?>
	<div class="crm-wrap"><header class="crm-hero"><div><small>FINANCIAL OVERVIEW</small><h1>Annual Revenue Report</h1><p>Sales, actual cash received, costs and gross profit.</p></div><form><input type="hidden" name="page" value="co-project-report"><select name="report_year" onchange="this.form.submit()"><?php for ( $y = (int) wp_date( 'Y' ); $y >= (int) wp_date( 'Y' ) - 6; $y-- ) : ?><option <?php selected( $year, $y ); ?>><?php echo $y; ?></option><?php endfor; ?></select></form></header><section class="crm-stats"><div><small>Agreed sales</small><strong>฿<?php echo co_crm_money( $sales ); ?></strong></div><div><small>Cash received</small><strong>฿<?php echo co_crm_money( $cash ); ?></strong></div><div><small>Estimated costs</small><strong>฿<?php echo co_crm_money( $cost ); ?></strong></div><div><small>Gross profit</small><strong>฿<?php echo co_crm_money( $sales - $cost ); ?></strong></div></section><section class="crm-panel crm-chart"><h2>Cash received by month</h2><?php $max = max( 1, max( $months ) ); foreach ( $months as $month => $amount ) : ?><div><span><?php echo esc_html( wp_date( 'M', mktime( 0, 0, 0, $month, 1 ) ) ); ?></span><i><b style="width:<?php echo esc_attr( $amount / $max * 100 ); ?>%"></b></i><strong>฿<?php echo co_crm_money( $amount ); ?></strong></div><?php endforeach; ?></section></div>
<?php }
